class Calc:
    def __init__(self, precision=2):
        self.precision = precision
        self.history = []

    def total(self, items):
        s = 0.0
        for it in items:
            s += it.price * it.qty
        self.history.append(s)
        return round(s, self.precision)

    def clear(self):
        self.history = []
